UPDATE t_question q
SET question_type = e.new_type,
    option_json = coalesce(e.new_options, q.option_json),
    correct = e.new_correct,
    blank_count = 1
FROM type45_map e
WHERE q.id = e.id AND NOT q.is_golden;
