UPDATE practice_session s
SET score = coalesce((SELECT sum(a.score_got) FROM practice_answer a
                      WHERE a.session_id = s.id AND a.deleted_at IS NULL), 0),
    correct_count = coalesce((SELECT count(*) FROM practice_answer a
                              WHERE a.session_id = s.id AND a.deleted_at IS NULL AND a.is_correct), 0)
WHERE s.id IN (SELECT DISTINCT session_id FROM practice_answer_backup_20261117_type45)
  AND s.finished_at IS NOT NULL;
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n
    FROM t_question q JOIN type45_map e ON e.id = q.id
   WHERE q.question_type = e.new_type
     AND q.correct = e.new_correct
     AND q.blank_count = 1
     AND (e.new_options IS NULL OR q.option_json = e.new_options);
  IF n <> 175 THEN RAISE EXCEPTION '转换数应为 175，实际 %', n; END IF;

  SELECT count(*) INTO n FROM t_question q JOIN type45_map e ON e.id = q.id WHERE q.is_golden;
  IF n <> 0 THEN RAISE EXCEPTION '触及金标 % 道', n; END IF;

  SELECT count(*) INTO n FROM t_question WHERE NOT deleted AND question_type=1;
  IF n <> 23965 THEN RAISE EXCEPTION 'type1 应为 23965，实际 %', n; END IF;
  SELECT count(*) INTO n FROM t_question WHERE NOT deleted AND question_type=2;
  IF n <> 3369 THEN RAISE EXCEPTION 'type2 应为 3369，实际 %', n; END IF;
  SELECT count(*) INTO n FROM t_question WHERE NOT deleted AND question_type=3;
  IF n <> 7388 THEN RAISE EXCEPTION 'type3 应为 7388，实际 %', n; END IF;
  SELECT count(*) INTO n FROM t_question WHERE NOT deleted AND question_type=4;
