  SELECT count(*) INTO n FROM t_question WHERE is_golden;
  IF n <> 200 THEN RAISE EXCEPTION '金标应为 200，实际 %', n; END IF;

  SELECT count(*) INTO n FROM practice_answer WHERE question_id IN (334600,334849,334861,334862,334864,334867,334868,334991,338200,338297,338303,341674,342085,342087,342093,342161,342163,342164,342165,342167,342182,342183,342212,342213,342248,342249,345154,345155,345252,345468,345469,347849,347850,348068,348081,348089,348090,348096,351410,352588,353459,356507,361009,361012,361013,364009,364742,364743,364752,364759,364780,364873,364874,364877,364979,364987,364991,364992,364995,364996,364997,365837,365895,365897,366256,366322,366324,366518,366573,366692,366697,366700,366701,366704,366997,367014,367040,367042,367045,367046,367048,367049,367058,367059,367060,367063,367145,367154,367192,367203,367271,367272,367325,367344,367345,367346,367347,367348,367350,367351,367352,367353,367364,367762,367793,367876,367896,368368,368476,368479,368482,368489,368511,368513,368675,368677,368684,368685,368702,369316,369357,369395,369418,369801,369831,369841,369853,369875,369920,369923,369931,369950,370426,370671,370863,371002,371028,371029,371070,371229,372997,373122,374769,374778,374880,374881,374882,374885,374902,375973,376217,376220,376422,376475,377379,377402,377430,377435,377444,377445,377454,377472,377484,377487,377489,377495,377498,377499,377500,377530,377531,377532,377535,377658,380477);
  IF n <> 0 THEN RAISE EXCEPTION '仍有做题记录 %', n; END IF;
